def xlsx_to_csv_text(content: bytes) -> str:
    """Convert the first sheet of an XLSX file to CSV text, keeping sheet row numbers."""
    from openpyxl import load_workbook

    workbook = load_workbook(io.BytesIO(content), read_only=True, data_only=True)
    try:
        sheet = workbook.worksheets[0]
        out = io.StringIO()
        writer = csv.writer(out, lineterminator='\n')
        for cells in sheet.iter_rows(values_only=True):
            writer.writerow(
                ['' if c is None else str(c).replace('\r', ' ').replace('\n', ' ') for c in cells]
            )
        return out.getvalue()
    finally:
        workbook.close()


def validate_user_upload(filename: str, content: bytes, max_rows: int=MAX_ROWS) -> list[dict[str, Any]]:
    """Validate an uploaded CSV/XLSX of new users.

    Returns only the bad rows as [{"row": <spreadsheet row number, header = 1>,
    "errors": [<reason>, ...]}], reporting every problem rather than stopping at the first.
    """
    extension = os.path.splitext(filename or '')[1].lower()
    if extension == '.xlsx':
        try:
            text = xlsx_to_csv_text(content)
        except Exception:
            return [{'row': 1, 'errors': ['could not read the XLSX file']}]
    elif extension == '.csv':
        try:
            text = content.decode('utf-8-sig')
        except UnicodeDecodeError:
            return [{'row': 1, 'errors': ['CSV file is not valid UTF-8']}]
    else:
        return [{'row': 1, 'errors': ['unsupported file type; upload a .csv or .xlsx file']}]
    _, errors = import_users(text, max_rows=max_rows)
    return errors

